import * as qs from 'qs';
import { DeviceTypeOptions } from '../types';
import { userAgent } from '../user-agent';

const PHONE_PORTRAIT_WIDTH_BREAKPOINT = 450;
const PHONE_LANDSCAPE_WIDTH_BREAKPOINT = 750;
const TABLET_PORTRAIT_WIDTH_BREAKPOINT = 1024;
const TABLET_LANDSCAPE_WIDTH_BREAKPOINT = 1366;

const PHONE_WIDTH_BREAKPOINT = Math.max(PHONE_PORTRAIT_WIDTH_BREAKPOINT, PHONE_LANDSCAPE_WIDTH_BREAKPOINT);
const TABLET_WIDTH_BREAKPOINT = Math.max(TABLET_PORTRAIT_WIDTH_BREAKPOINT, TABLET_LANDSCAPE_WIDTH_BREAKPOINT);

const THIN_TABLET_ASPECT_RATIO_BREAKPOINT = 0.7;

const IPHONE_X_WIDTH = 1125;
const IPHONE_X_HEIGHT = 2436;
const IPHONE_XR_WIDTH = 828;
const IPHONE_XR_HEIGHT = 1792;

const isMobilePretendingToBeDesktop = ('ontouchstart' in window);
const isIPadPretendingToBeDesktop = isMobilePretendingToBeDesktop && userAgent.os.name === 'Mac OS';
const isNotIOS = (userAgent.os.name && !userAgent.os.name.includes('iOS'));
const isMobileOS = userAgent.os.name && (userAgent.os.name.includes('Android') || userAgent.os.name.includes('iOS') || userAgent.os.name.includes('Windows Phone'));

let queryString: qs.ParsedQs | undefined;
export class DeviceType {
    public readonly value: DeviceTypeOptions;

    public readonly realValue: DeviceTypeOptions;

    constructor(forcedType: DeviceTypeOptions | undefined = undefined) {
        this.realValue = this.determineType();
        this.value = forcedType ?? this.realValue;
    }

    public get isMobile(): boolean {
        return this.value === 'mobile';
    }

    public get isTablet(): boolean {
        return this.value === 'tablet';
    }

    public get isDesktop(): boolean {
        return this.value === 'desktop';
    }

    public get isApp(): boolean {
        if (!queryString) {
            queryString = qs.parse(window.location.search.replace('?', ''));
        }

        return (!!queryString.host &&
            (queryString.host === 'hybrid' ||
                queryString.host === 'android' ||
                queryString.host === 'ios'));
    }

    public get isHybrid(): boolean {
        if (!queryString) {
            queryString = qs.parse(window.location.search.replace('?', ''));
        }

        const host = queryString.host;
        return (host === 'hybrid');
    }

    public get isNative(): boolean {
        if (!queryString) {
            queryString = qs.parse(window.location.search.replace('?', ''));
        }

        const host = queryString.host;
        return (host === 'android' || host === 'ios');
    }

    public get isAndroidNative(): boolean {
        if (!queryString) {
            queryString = qs.parse(window.location.search.replace('?', ''));
        }

        const host = queryString.host;
        return (host === 'android');
    }

    public get isIosNative(): boolean {
        if (!queryString) {
            queryString = qs.parse(window.location.search.replace('?', ''));
        }

        const host = queryString.host;
        return (host === 'ios');
    }

    private determineType(): DeviceTypeOptions {
        if (isIPadPretendingToBeDesktop) {
            return 'tablet';
        }
        if (!userAgent.device.type) {
            if (!isMobileOS) {
                return 'desktop';
            } else if (window.innerWidth <= PHONE_WIDTH_BREAKPOINT) {
                return 'mobile';
            } else if (window.innerWidth <= TABLET_WIDTH_BREAKPOINT) {
                return isNotIOS ? this.isTabletOrMobile() : 'tablet';
            }
            return 'desktop';
        }
        return userAgent.device.type === 'tablet' && isNotIOS ? this.isTabletOrMobile() : userAgent.device.type as DeviceTypeOptions;
    }

    private isTabletOrMobile() {
        const width = window.screen.width;
        const height = window.screen.height;
        const aspectRatio = Math.min(width, height) / Math.max(width, height);
        const isThin = window.innerWidth <= Math.max(PHONE_LANDSCAPE_WIDTH_BREAKPOINT, TABLET_PORTRAIT_WIDTH_BREAKPOINT);
        if (aspectRatio < THIN_TABLET_ASPECT_RATIO_BREAKPOINT && isThin) {
            return 'mobile';
        }
        return 'tablet';
    }

    // basically until browsers decide they are going to be helpful and let us know if something is foldable, this is as good as it gets
    get isFoldable() {
        // G9FPL is google fold
        // SM-F9 is galaxy fold
        // VER-AN10 is Honor Magic V2
        return /SM-F9|G9FPL|VER-AN10/i.test(userAgent.ua);
    }

    public static get isKindle() {
        return /Kindle Fire|Silk|KFAPWA|KFSOWI|KFJWA|KFJWI|KFAPWI|KFOT|KFTT|KFTHWI|KFTHWA|KFASWI|KFTBWI|KFMEWI|KFFOWI|KFSAWA|KFSAWI|KFARWI|KFGIWI|KFAUWI|KFDOWI|KFSUWI|KFKAWI|KFMUWI|KFMAWI|KFONWI/i.test(userAgent.ua);
    }

    public static get isIphoneX() {
        const isIos = /iPad|iPhone|iPod/.test(userAgent.ua) && !(window as any).MSStream;
        const ratio = window.devicePixelRatio || 1;
        const screen = {
            width: window.screen.width * ratio,
            height: window.screen.height * ratio
        };
        return isIos && (screen.width === IPHONE_X_WIDTH && screen.height === IPHONE_X_HEIGHT) ||
            (screen.width === IPHONE_XR_WIDTH && screen.height === IPHONE_XR_HEIGHT);
    }
}